data_types.code:
set str "Hello"
set num 42
set lst {1 2 3}
array set map {key value}

conditionals.code:
if {$val > 10} {
    puts "Greater"
} elseif {$val == 10} {
    puts "Equal"
} else {
    puts "Lesser"
}

for_loop.code:
for {set i 0} {$i < 5} {incr i} {
    puts $i
}

foreach item {apple banana cherry} {
    puts $item
}

while_loop.code:
set count 1
while {$count <= 5} {
    puts $count
    incr count
}

error_handling.code:
if {[catch {open "nonexistent.txt" r} fp]} {
    puts "Error opening file: $fp"
} else {
    puts "File opened successfully"
    close $fp
}

comments.code:
# Single line comment in Tcl
# Shell scripts begin with a shebang:
#!/usr/bin/env tcl

pattern_matching.code:
case "$val" in
    1) echo "One" ;;
    2|3) echo "Two or Three" ;;
    *) echo "Other" ;;
esac

oop_classes.code:
# Functions serve as reusable components
person_greet() {
    local name="$1"
    echo "Hello $name"
}
